BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch05$PT107-S3-Q11$batch05$ AND q.stimulus=$batch05$Astronomer: Astronomical observations in many areas have become useless because light from nearby cities obscures the stars Many people argue that since streetlights are needed for safety, such interference from lights is inevitable. Here in Sandsville, however, the local observatory’s view remains relatively clear, since the city has restricted unnecessary lighting and installed special street lamps that direct all their light downward. It is therefore possible to have both well-lighted streets and relatively dark skies.$batch05$ AND q.prompt=$batch05$The astronomer's argument proceeds by$batch05$ AND q.correct_choice=$batch05$E$batch05$) THEN RAISE EXCEPTION 'Question changed: PT107-S3-Q11'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch05$PT107-S3-Q11$batch05$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT107-S3-Q11'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch05$PT107-S3-Q11$batch05$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch05$Conclusion$batch05$, $batch05$It is possible to have both well-lit streets and fairly dark skies.$batch05$), (1, $batch05$Evidence$batch05$, $batch05$Sandsville restricted unnecessary lighting and uses lamps that point down, and its observatory's view stays fairly clear.$batch05$), (2, $batch05$Evaluate$batch05$, $batch05$Many people say light interference is *inevitable*. "Inevitable" is a sweeping claim, and one real case can break it. Sandsville is that case: safe streets and dark skies, together.$batch05$), (3, $batch05$Goal$batch05$, $batch05$A counterexample to a general claim.$batch05$)) v(position,label,body) WHERE q.qid=$batch05$PT107-S3-Q11$batch05$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch05$A$batch05$, $batch05$Sandsville is a town, not a scientific authority.$batch05$), ($batch05$B$batch05$, $batch05$This is the most popular wrong answer. But the astronomer accepts the opposing side's evidence: streetlights are needed for safety. Sandsville still has well-lit streets. What fails is the step from "we need streetlights" to "interference is inevitable."$batch05$), ($batch05$C$batch05$, $batch05$No natural phenomenon gets a new explanation.$batch05$), ($batch05$D$batch05$, $batch05$No terms are distinguished.$batch05$), ($batch05$E$batch05$, $batch05$The general claim is that interference is inevitable. Sandsville is the counterexample.$batch05$)) v(letter,body) WHERE q.qid=$batch05$PT107-S3-Q11$batch05$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
